mapper.select:
select w.id, w.name, w.description, w.status, w.owner_id, w.dept_id, d.dept_name as dept_name, u.nick_name as owner_name, (select count(*) from agent_workspace_member cm where cm.workspace_id = w.id) as member_count, w.create_time, w.update_time from agent_workspace w left join sys_user u on u.user_id = w.owner_id left join sys_dept d on d.dept_id = w.dept_id where w.del_flag = 0
and w.name like concat('%', #{keyword}, '%')
and w.status = #{status}
and w.dept_id = #{deptId}
order by w.create_time desc
